            { "FileAttributes.Hidden", "The file is hidden, and thus is not included in an ordinary directory listing. Hidden is supported on Windows, Linux, and macOS." },
            { "FileAttributes.IntegrityStream", "The file or directory includes data integrity support. When this value is applied to a file, all data streams in the file have integrity support. When this value is applied to a directory, all new files and subdirectories within that directory, by default, include integrity support." },
            { "FileAttributes.Normal", "The file is a standard file that has no special attributes. This attribute is valid only if it is used alone. Normal is supported on Windows, Linux, and macOS." },
            { "FileAttributes.NoScrubData", "The file or directory is excluded from the data integrity scan. When this value is applied to a directory, by default, all new files and subdirectories within that directory are excluded from data integrity." },
