            { "FileStream.BeginWrite", "Begins an asynchronous write operation. Consider using System.IO.FileStream.WriteAsync(System.Byte[],System.Int32,System.Int32,System.Threading.CancellationToken) instead." },
            { "FileStream.CanRead", "Gets a value that indicates whether the current stream supports reading." },
