            { "FileStream.EndWrite", "Ends an asynchronous write operation and blocks until the I/O operation is complete. (Consider using System.IO.FileStream.WriteAsync(System.Byte[],System.Int32,System.Int32,System.Threading.CancellationToken) instead.)" },
            { "FileStream.Finalize", "Ensures that resources are freed and other cleanup operations are performed when the garbage collector reclaims the FileStream." },
