            { "FileStream.SetLength", "Sets the length of this stream to the given value." },
            { "FileStream.Unlock", "Allows access by other processes to all or part of a file that was previously locked." },
            { "FileStream.Write", "Writes a sequence of bytes from a read-only span to the current file stream and advances the current position within this file stream by the number of bytes written." },
