            { "BindingFlags.InvokeMethod", "Specifies that a method is to be invoked. This must not be a constructor or a type initializer.  " },
            { "BindingFlags.NonPublic", "Specifies that non-public members are to be included in the search." },
            { "BindingFlags.OptionalParamBinding", "Returns the set of members whose parameter count matches the number of supplied arguments. This binding flag is used for methods with parameters that have default values and methods with variable arguments (varargs). This flag should only be used with System.Type.InvokeMember(System.String,System.Reflection.BindingFlags,System.Reflection.Binder,System.Object,System.Object[],System.Reflection.ParameterModifier[],System.Globalization.CultureInfo,System.String[]).<br /><br />Parameters with default values are used only in calls where trailing arguments are omitted. They must be the last arguments." },
            { "BindingFlags.Public", "Specifies that public members are to be included in the search." },
            { "BindingFlags.PutDispProperty", "Specifies that the PROPPUT member on a COM object should be invoked. PROPPUT specifies a property-setting function that uses a value. Use PutDispProperty if a property has both PROPPUT and PROPPUTREF and you need to distinguish which one is called." },
            { "BindingFlags.PutRefDispProperty", "Specifies that the PROPPUTREF member on a COM object should be invoked. PROPPUTREF specifies a property-setting function that uses a reference instead of a value. Use PutRefDispProperty if a property has both PROPPUT and PROPPUTREF and you need to distinguish which one is called." },
            { "BindingFlags.SetField", "Specifies that the value of the specified field should be set.  " },
            { "BindingFlags.SetProperty", "Specifies that the value of the specified property should be set. For COM properties, specifying this binding flag is equivalent to specifying PutDispProperty and PutRefDispProperty.  " },
            { "BindingFlags.Static", "Specifies that static members are to be included in the search." },
            { "BindingFlags.SuppressChangeType", "Not implemented." },
            { "CallingConventions", "Defines the valid calling conventions for a method." },
            { "CallingConventions.Any", "Specifies that either the Standard or the VarArgs calling convention may be used." },
            { "CallingConventions.ExplicitThis", "Specifies that the signature is a function-pointer signature, representing a call to an instance or virtual method (not a static method). If ExplicitThis is set, HasThis must also be set. The first argument passed to the called method is still a this pointer, but the type of the first argument is now unknown. Therefore, a token that describes the type (or class) of the this pointer is explicitly stored into its metadata signature." },
            { "CallingConventions.HasThis", "Specifies an instance or virtual method (not a static method). At run-time, the called method is passed a pointer to the target object as its first argument (the this pointer). The signature stored in metadata does not include the type of this first argument, because the method is known and its owner class can be discovered from metadata." },
            { "CallingConventions.Standard", "Specifies the default calling convention as determined by the common language runtime. Use this calling convention for static methods. For instance or virtual methods use HasThis." },
            { "CallingConventions.VarArgs", "Specifies the calling convention for methods with variable arguments." },
